import{_ as a,o as n,c as l,a3 as i}from"./chunks/framework.MGD2uYU7.js";const g=JSON.parse('{"title":"SC-10 — Đăng ký","description":"","frontmatter":{"title":"SC-10 — Đăng ký"},"headers":[],"relativePath":"wireframes/auth/sc-10-dang-ky.md","filePath":"wireframes/auth/sc-10-dang-ky.md","lastUpdated":1791606799000}'),t={name:"wireframes/auth/sc-10-dang-ky.md"};function c(p,s,e,d,o,r){return n(),l("div",null,[...s[0]||(s[0]=[i('<h1 id="sc-10-—-đang-ky-tai-khoan" tabindex="-1">SC-10 — Đăng ký tài khoản <a class="header-anchor" href="#sc-10-—-đang-ky-tai-khoan" aria-label="Permalink to &quot;SC-10 — Đăng ký tài khoản&quot;">​</a></h1><p><span class="wf-badge info">Route: /dang-ky</span> <span class="wf-badge muted">Nguồn: docs/05 §3/§5 · docs/03 UC-01 · docs/02 FR-IDT-01 · docs/08 BR-IDT · docs/06 §5</span></p><p><strong>Ai xem màn này</strong>: Khách muốn đăng tin bán / đăng ký đấu giá / đặt lịch xem (bắt buộc có tài khoản) · Khách bấm CTA &quot;Đăng bán&quot;/&quot;Đăng ký&quot; từ trang chủ, bảng gói (login-intent). <strong>Mục đích / cảm xúc thiết kế</strong>: đăng ký nhẹ nhất có thể (chỉ 3 trường bắt buộc theo FR-IDT-01) nhưng <strong>minh bạch ngay từ đầu</strong> về sức mạnh mật khẩu và điều khoản dữ liệu cá nhân (NĐ13). Thành công = toast + auto-login → SC-20, không bắt user quay lại đăng nhập lần nữa. <strong>Ví dụ số dùng trong bản vẽ</strong>: user mới <code>Nguyễn Văn Demo</code> · email <code>demo@example.com</code> · SĐT <code>09xx xxx xxx</code>; user vừa xem căn <code>CT2-A18.05</code> — NOXH <code>HP-380</code> giá <code>1.250.000.000 ₫</code> (deep-link return sau đăng ký).</p><h2 id="_1-desktop-—-form-trang-thai-binh-thuong" tabindex="-1">1. Desktop — form trạng thái bình thường <a class="header-anchor" href="#_1-desktop-—-form-trang-thai-binh-thuong" aria-label="Permalink to &quot;1. Desktop — form trạng thái bình thường&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/dang-ky?next=/nha-o-xa-hoi/lst_01JZK3M9W2Q8</span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span>Mua nhà</span><span>Đấu giá</span><span>Bảng gói</span><span>Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-btn sm">Đăng nhập</span></span></div><div class="wf-container"><div class="wf-col" style="max-width:460px;margin:24px auto;gap:12px;"><div class="wf-toast info">Tạo tài khoản để tiếp tục — xong sẽ tự quay lại trang căn <b>CT2-A18.05</b> bạn đang xem <span class="wf-callout">1</span></div><div class="wf-card"><div class="pad wf-col" style="gap:14px;"><div class="wf-col" style="gap:2px;"><span class="wf-title lg">Đăng ký miễn phí</span><span class="wf-small">Miễn phí 2 tin đăng · tham gia đấu giá sau khi xác minh CCCD (SC-21)</span></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Họ và tên <span class="wf-danger-text">*</span></span><div class="wf-input filled"><span>Nguyễn Văn Demo</span><span class="caret">✎</span></div><span class="wf-small wf-muted">2–100 ký tự. Nên trùng giấy tờ — tên trên CCCD sẽ được đối chiếu khi xác minh <span class="wf-callout">2</span></span></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Email <span class="wf-danger-text">*</span></span><div class="wf-input filled"><span>demo@example.com</span><span class="caret">✎</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Số điện thoại <span class="wf-muted">(không bắt buộc)</span></span><div class="wf-input"><span>09xx xxx xxx</span><span class="caret">✎</span></div><span class="wf-small wf-muted">Chỉ dùng để CSKH liên hệ về tài khoản</span></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Mật khẩu <span class="wf-danger-text">*</span></span><div class="wf-input filled"><span>Anphuc@2026</span><span class="caret">👁</span></div><div class="wf-row" style="gap:4px;margin-top:4px;"><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-ok);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-ok);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-ok);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-ok);"></span></div><div class="wf-row between"><span class="wf-small wf-ok-text"><b>Mạnh</b> <span class="wf-callout">3</span></span><span class="wf-small wf-muted">≥8 ký tự · 1 hoa · 1 số · 1 đặc biệt</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Xác nhận mật khẩu <span class="wf-danger-text">*</span></span><div class="wf-input filled"><span>Anphuc@2026</span><span class="caret">👁</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-checkbox checked">Tôi đồng ý <b>Quy chế hoạt động</b> và <b>Chính sách bảo vệ dữ liệu cá nhân</b> (NĐ13/2023/NĐ-CP) <span class="wf-callout">4</span></span></div><span class="wf-btn primary lg block">Đăng ký <span class="wf-callout" style="background:#fff;color:var(--wf-accent);">5</span></span><div class="wf-center"><span class="wf-small">Đã có tài khoản? <b class="wf-accent">Đăng nhập</b> → SC-09</span></div></div></div><span class="wf-small wf-center">CSKH 1900-xxx · Quy chế hoạt động · Chính sách bảo mật</span></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/05 §3/§5 · docs/03 UC-01 · docs/08 BR-IDT)</div><ol><li><span class="num">1</span><span><b>Deep-link return</b>: <code>?next=</code> như SC-09 — đăng ký thành công → auto-login → quay lại đúng trang đang xem; không có <code>next</code> → SC-20 Dashboard. <span class="ref">docs/05 §2</span> <span class="ref">UC-03 AF-1</span></span></li><li><span class="num">2</span><span>Họ tên 2–100 ký tự (FR-IDT-01). Ghi chú &quot;trùng CCCD&quot; chuẩn bị cho KYC: ADMIN đối chiếu tên user ↔ tên trên CCCD khi duyệt — sai lệch sẽ bị reject. <span class="ref">BR-KYC-02</span></span></li><li><span class="num">3</span><span><b>Strength meter</b> tính client-side realtime khi gõ (không gửi server để đo): 4 vạch + nhãn Yếu/Trung bình/Mạnh theo đúng rule BR-IDT-02 (≥8 ký tự, ≥1 hoa, ≥1 số, ≥1 ký tự đặc biệt). Meter là <b>gợi ý</b>, không chặn submit — server mới là trọng tài (400 <code>VALIDATION_ERROR</code> theo field). <span class="ref">BR-IDT-02</span> <span class="ref">docs/05 §3 SC-09/10</span></span></li><li><span class="num">4</span><span>Checkbox điều khoản <b>bắt buộc tick</b>; chưa tick mà bấm Đăng ký → <code>wf-field-error</code> cạnh checkbox: &quot;Vui lòng đồng ý điều khoản để tiếp tục&quot; (copy FE — không thuộc docs/06 §5). Link điều khoản mở tab mới. <span class="ref">docs/05 §1.5</span></span></li><li><span class="num">5</span><span><b>Submit</b>: <code>POST /auth/register</code> (rate limit 3 lần/giờ/IP) → nút loading disabled; 201 → toast thành công + <b>auto-login</b> (không bắt đăng nhập lại) → redirect SC-20. User tạo ra có <code>status=ACTIVE</code>, <code>kycStatus=NONE</code> — dashboard sẽ nhắc xác minh. <span class="ref">docs/05 §5</span> <span class="ref">UC-01 MF</span> <span class="ref">FR-IDT-01</span></span></li></ol></div><h2 id="_2-password-strength-meter-—-3-trang-thai" tabindex="-1">2. Password strength meter — 3 trạng thái <a class="header-anchor" href="#_2-password-strength-meter-—-3-trang-thai" aria-label="Permalink to &quot;2. Password strength meter — 3 trạng thái&quot;">​</a></h2><div class="wf"><div class="wf-grid cols-3"><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: YẾU</span><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><span class="wf-small wf-strong">Mật khẩu</span><div class="wf-input filled error"><span>anphuc</span><span class="caret">👁</span></div><div class="wf-row" style="gap:4px;"><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-danger);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-fill-dark);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-fill-dark);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-fill-dark);"></span></div><span class="wf-small wf-danger-text"><b>Yếu</b> — chưa đạt yêu cầu</span><span class="wf-field-error">Thiếu: ≥8 ký tự · 1 chữ hoa · 1 ký tự đặc biệt <span class="wf-callout danger">6</span></span></div></div></div><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: TRUNG BÌNH</span><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><span class="wf-small wf-strong">Mật khẩu</span><div class="wf-input filled"><span>Anphuc2026</span><span class="caret">👁</span></div><div class="wf-row" style="gap:4px;"><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-warn);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-warn);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-warn);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-fill-dark);"></span></div><span class="wf-small wf-warn-text"><b>Trung bình</b> — dùng được, nên thêm ký tự đặc biệt</span></div></div></div><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: MẠNH</span><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><span class="wf-small wf-strong">Mật khẩu</span><div class="wf-input filled"><span>Anphuc@2026</span><span class="caret">👁</span></div><div class="wf-row" style="gap:4px;"><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-ok);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-ok);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-ok);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-ok);"></span></div><span class="wf-small wf-ok-text"><b>Mạnh</b> ✓ đủ 4 điều kiện</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích strength meter</div><ol><li><span class="num">6</span><span>Vạch meter đổi màu theo số điều kiện đạt (danger → warn → ok); khi Yếu liệt kê <b>đúng điều kiện còn thiếu</b> thay vì chê chung chung. &quot;Xác nhận mật khẩu&quot; lệch → field error tại ô confirm: &quot;Mật khẩu xác nhận không khớp&quot;. Rule cứng nằm ở server (argon2id, BR-IDT-02) — meter chỉ phản ánh đúng 4 điều kiện đó, không tự chế thang điểm riêng. <span class="ref">BR-IDT-02</span> <span class="ref">UC-01 EF-2</span></span></li></ol></div><h2 id="_3-desktop-—-trang-thai-loi-409-400-429" tabindex="-1">3. Desktop — trạng thái lỗi (409 / 400 / 429) <a class="header-anchor" href="#_3-desktop-—-trang-thai-loi-409-400-429" aria-label="Permalink to &quot;3. Desktop — trạng thái lỗi (409 / 400 / 429)&quot;">​</a></h2><div class="wf"><div class="wf-grid"><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: 409 — EMAIL ĐÃ TỒN TẠI (AUTH_EMAIL_TAKEN)</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><span class="wf-small wf-strong">Email</span><div class="wf-input filled error"><span>demo@example.com</span><span class="caret">✎</span></div><span class="wf-field-error">Email đã được sử dụng. Đăng nhập hoặc liên hệ hỗ trợ <span class="wf-callout danger">7</span></span><span class="wf-small">Email này đã có tài khoản — <b class="wf-accent">Đăng nhập</b> · Quên mật khẩu? Gọi CSKH 1900-xxx</span></div></div></div><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: 400 — VALIDATION THEO FIELD</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><span class="wf-small wf-strong">Họ và tên</span><div class="wf-input filled error"><span>D</span><span class="caret">✎</span></div><span class="wf-field-error">Họ tên phải từ 2–100 ký tự</span><span class="wf-small wf-strong">Mật khẩu</span><div class="wf-input filled error"><span>anphuc</span><span class="caret">👁</span></div><span class="wf-field-error">Mật khẩu phải ≥8 ký tự, có chữ hoa, số và ký tự đặc biệt <span class="wf-callout danger">8</span></span></div></div></div><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: 429 — QUÁ 3 LẦN ĐĂNG KÝ / GIỜ / IP</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-toast warn">Thiết bị này vừa tạo nhiều tài khoản — vui lòng thử lại sau <span class="wf-callout warn">9</span></div><span class="wf-btn disabled block">Đăng ký (tạm khóa)</span><span class="wf-small">Nút tự mở lại khi hết cửa sổ giới hạn (đếm theo server). Nghi ngờ bị chặn nhầm? Gọi CSKH 1900-xxx kèm traceId.</span></div></div></div><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: THÀNH CÔNG — TOAST + AUTO-LOGIN</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-toast ok">✓ Đăng ký thành công — chào mừng Nguyễn Văn Demo! Đang chuyển đến bảng điều khiển… <span class="wf-callout">10</span></div><div class="wf-skeleton" style="height:60px;"></div><span class="wf-small">Không hiện màn &quot;đăng nhập lại&quot;: token đã phát hành ngay trong response register. Redirect về <code>?next=</code> hoặc SC-20 — dashboard mở đầu bằng checklist onboarding (KYC → đăng tin → VIP).</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích lỗi</div><ol><li><span class="num">7</span><span>409 <code>AUTH_EMAIL_TAKEN</code> — message <b>nguyên văn docs/06 §5</b>: &quot;Email đã được sử dụng. Đăng nhập hoặc liên hệ hỗ trợ&quot;. Gắn ngay dưới field email (không phải toast chung) + link tắt sang SC-09 prefill email. <span class="ref">UC-01 EF-1</span> <span class="ref">BR-IDT-01</span> <span class="ref">docs/06 §5</span></span></li><li><span class="num">8</span><span>400 <code>VALIDATION_ERROR</code>: server trả <code>errors[]</code> theo field → FE map về đúng ô (onSubmit); client cũng validate trước onBlur + onSubmit cùng bộ string. Email normalize lowercase trước khi check unique. <span class="ref">docs/05 §1.5</span> <span class="ref">FR-IDT-01</span> <span class="ref">BR-IDT-01</span></span></li><li><span class="num">9</span><span>Register rate limit 3/giờ/IP (docs/06 §3 endpoint 1) — chống tạo tài khoản hàng loạt. <span class="ref">NFR-S-02</span></span></li><li><span class="num">10</span><span>Thành công: toast ok tự ẩn ~3s, skeleton dashboard trong lúc redirect. Đây chính là hành vi cột &quot;Đăng ký (SC-10)&quot; của Behavior Matrix: toast + auto-login → SC-20. <span class="ref">docs/05 §5</span></span></li></ol></div><h2 id="_4-mobile-360px-—-form-đang-ky" tabindex="-1">4. Mobile 360px — form đăng ký <a class="header-anchor" href="#_4-mobile-360px-—-form-đang-ky" aria-label="Permalink to &quot;4. Mobile 360px — form đăng ký&quot;">​</a></h2><div class="wf"><div class="wf-row" style="justify-content:center;gap:20px;flex-wrap:wrap;"><div><span class="wf-state-label">MOBILE — FORM ĐĂNG KÝ</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-btn sm">Đăng nhập</span></div><div class="wf-container" style="padding:12px;"><div class="wf-col" style="gap:10px;"><span class="wf-title lg">Đăng ký miễn phí</span><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Họ và tên *</span><div class="wf-input filled"><span>Nguyễn Văn Demo</span><span class="caret">✎</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Email *</span><div class="wf-input filled"><span>demo@example.com</span><span class="caret">✎</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">SĐT <span class="wf-muted">(không bắt buộc)</span></span><div class="wf-input"><span>09xx xxx xxx</span><span class="caret">✎</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Mật khẩu *</span><div class="wf-input filled"><span>Anphuc@2026</span><span class="caret">👁</span></div><div class="wf-row" style="gap:4px;"><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-ok);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-ok);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-ok);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-ok);"></span></div><span class="wf-small wf-ok-text"><b>Mạnh</b> ✓</span></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Xác nhận mật khẩu *</span><div class="wf-input filled"><span>Anphuc@2026</span><span class="caret">👁</span></div></div><span class="wf-checkbox checked"><span class="wf-small">Đồng ý Quy chế + CS bảo mật (NĐ13)</span></span><span class="wf-btn primary lg block">Đăng ký</span><div class="wf-center"><span class="wf-small">Đã có tài khoản? <b class="wf-accent">Đăng nhập</b></span></div></div></div></div></div><div><span class="wf-state-label">MOBILE — 409 EMAIL TRÙNG</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-btn sm">Đăng nhập</span></div><div class="wf-container" style="padding:12px;"><div class="wf-col" style="gap:10px;"><span class="wf-title lg">Đăng ký miễn phí</span><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Email *</span><div class="wf-input filled error"><span>demo@example.com</span><span class="caret">✎</span></div><span class="wf-field-error">Email đã được sử dụng. Đăng nhập hoặc liên hệ hỗ trợ</span></div><span class="wf-btn block">Đăng nhập với email này</span><span class="wf-small wf-center">Quên mật khẩu? Gọi CSKH 1900-xxx</span></div></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích mobile</div><ol><li><span class="num">M</span><span>Thứ tự field giữ nguyên desktop; strength meter rút gọn còn 4 vạch + 1 nhãn (chi tiết điều kiện thiếu hiện khi chạm vào ô mật khẩu). Keyboard type theo từng ô (text/email/tel/password); lỗi scroll tự động tới field đầu tiên sai.</span></li></ol></div><h2 id="_5-checklist-designer-khi-dung-figma-cho-sc-10" tabindex="-1">5. Checklist designer khi dựng Figma cho SC-10 <a class="header-anchor" href="#_5-checklist-designer-khi-dung-figma-cho-sc-10" aria-label="Permalink to &quot;5. Checklist designer khi dựng Figma cho SC-10&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop (card giữa, max 460px) / mobile 360 / tablet 768</li><li>[ ] Đủ trạng thái: bình thường (có/không banner deep-link) · strength meter Yếu/Trung bình/Mạnh · 409 email trùng · 400 validation từng field · confirm lệch · 429 rate limit · loading nút · success toast + redirect</li><li>[ ] Strength meter: 4 vạch + nhãn, liệt kê điều kiện thiếu khi Yếu; không chặn submit phía client (server là trọng tài)</li><li>[ ] Copy đúng nguyên văn docs/06 §5: &quot;Email đã được sử dụng. Đăng nhập hoặc liên hệ hỗ trợ&quot;; các message field khác theo FR-IDT-01</li><li>[ ] Checkbox điều khoản bắt buộc, link Quy chế + CS bảo mật mở tab mới; ghi chú NĐ13 visible</li><li>[ ] Không emoji icon trong UI production (👁/✓ trong wireframe là placeholder — thay icon set thật)</li><li>[ ] Accessibility: label mọi input, aria-live cho strength meter + field error, focus ring, contrast AA</li><li>[ ] SĐT hiển thị dạng <code>09xx xxx xxx</code>; họ tên có hint &quot;trùng CCCD&quot; chuẩn bị cho SC-21</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ (vd rule mật khẩu, số trường bắt buộc) cần PM duyệt trên docs/08 trước.</p></div>',18)])])}const f=a(t,[["render",c]]);export{g as __pageData,f as default};
